// Parse HTML from Fetch node and extract structured data.
// Customize selectors for your target site.
const html = $input.first().json.data || $input.first().json.body || $input.first().json;
const text = typeof html === 'string' ? html : (html && html.toString ? html.toString() : '');

// Simple extractor: get all links and text (customize for your page).
const linkRegex = /<a[^>]+href=["']([^"']+)["'][^>]*>([^<]*)</gi;
const rows = [];
let m;
while ((m = linkRegex.exec(text)) !== null && rows.length < 100) {
  rows.push({ url: m[1].trim(), text: m[2].trim().replace(/\s+/g, ' ') });
}

// If no links found, add a placeholder row so the rest of the workflow runs.
if (rows.length === 0) {
  rows.push({ url: 'https://example.com', text: 'No links extracted - customize Parse HTML node' });
}

return rows.map(r => ({ json: r }));

const items = $input.all();
const headers = ['url', 'text'];
const lines = [headers.join(',')];
for (const item of items) {
  const j = item.json;
  const row = headers.map(h => (j[h] != null ? String(j[h]).replace(/"/g, '""') : ''));
  lines.push('"' + row.join('","') + '"');
}
const csvString = lines.join('\n');
const fileName = 'scraped-data-' + new Date().toISOString().slice(0,16).replace(/[-T]/g,'-') + '.csv';
const binary = await this.helpers.prepareBinaryData(Buffer.from(csvString, 'utf8'), fileName, 'text/csv');
return [{ json: { rowCount: items.length }, binary: { data: binary } }];
